  if (decision.kind === "blocker")
    return { kind: "blocker", state, blocker: decision.blocker };
  const frontier = rows[0].context;
  if (state.frontier !== null && state.frontier.number !== frontier.number)
    return {
      kind: "advance",
      state: { ...state, frontier, lastWaitKey: null },
      merged: state.frontier,
      frontier,
      remaining: active.length,
    };
  if (deadlinePassed(state.startedAt, options, now))
    return {
      kind: "timeout",
      state: { ...state, frontier },
      frontier,
      unmergedCount: active.length,
    };
  const row = rows[0];
  const pending =
    row.kind === "open" && row.ci.kind === "ci-pending" ? row.ci.pending : null;
  const reason =
    pending === null
      ? ({ kind: "merge-queue", unmergedCount: active.length } as const)
      : ({ kind: "pending-checks", pending } as const);
  const key =
    reason.kind === "pending-checks"
      ? `pending:${frontier.number}:${reason.pending.length}`
      : `queue:${frontier.number}:${reason.unmergedCount}`;
  return {
    kind: "waiting",
    state: { ...state, frontier, lastWaitKey: key },
    frontier,
    reason,
    emit: state.lastWaitKey !== key,
  };
}
export async function runQueued(args: {
  readonly dependencies: RunDependencies;
  readonly contexts: T.NonEmpty<T.PrContext>;
  readonly options: T.PollingOptions;
}): Promise<T.QueueTerminalVerdict> {
  let state = createQueueState(args.contexts, args.dependencies.clock.now());
  const stamp = verdictFactory(args.dependencies.clock, "queued-stack");
  args.dependencies.emit(
    stamp({ kind: "QUEUE", terminal: false, queue: args.contexts })
  );
  const step = async (): Promise<StepResult<T.QueueTerminalVerdict>> => {
    state = planQueue(state, args.dependencies.clock.now());
    if (state.work === null) {
      const complete = evaluateQueue(
        state,
        args.dependencies.clock.now(),
        args.options
      );
      if (complete.kind !== "complete")
        throw new Error("queue has no work while active");
      return {
        kind: "terminal",
        verdict: stamp({
          kind: "COMPLETE",
          terminal: true,
          exitCode: 0,
          queue: state.queue,
          merged: complete.merged,
        }),
      };
    }
    const context =
      state.work.kind === "whole-stack-sweep"
        ? state.work.remaining[0]
        : state.work.frontier;
    const snapshot = await readSnapshot({
      reader: args.dependencies.reader,
      context,
      pendingHistory: "omit",
      allowDraft: args.options.allowDraft,
    });
    const applied = applyQueueSnapshot(
      state,
      snapshot,
      args.dependencies.clock.now(),
      args.options
    );
    state = applied.state;
    if (applied.completedSweepRows !== null)
      args.dependencies.emit(
        stamp({
          kind: "STATUS",
          terminal: false,
          reason: "whole-stack-sweep",
          rows: applied.completedSweepRows,
        })
      );
    if (state.work !== null) return { kind: "continue" };
    const evaluation = evaluateQueue(
      state,
      args.dependencies.clock.now(),
      args.options
    );
    state = evaluation.state;
    switch (evaluation.kind) {
      case "complete":
        return {
          kind: "terminal",
          verdict: stamp({
            kind: "COMPLETE",
            terminal: true,
            exitCode: 0,
            queue: state.queue,
            merged: evaluation.merged,
          }),
        };
      case "blocker":
        return {
          kind: "terminal",
          verdict: blockerVerdict(stamp, evaluation.blocker),
        };
      case "advance":
        args.dependencies.emit(
          stamp({
            kind: "ADVANCE",
            terminal: false,
            merged: evaluation.merged,
            frontier: evaluation.frontier,
            remaining: evaluation.remaining,
          })
        );
        return { kind: "continue" };
      case "timeout":
        return {
          kind: "terminal",
          verdict: stamp({
            kind: "TIMEOUT",
            terminal: true,
            exitCode: 5,
            reason: {
              kind: "queued-stack",
              frontier: evaluation.frontier,
              unmergedCount: evaluation.unmergedCount,
            },
          }),
        };
      case "waiting":
        if (evaluation.emit)
          args.dependencies.emit(
            stamp({
              kind: "WAITING",
              terminal: false,
              frontier: evaluation.frontier,
              reason: evaluation.reason,
            })
          );
        return { kind: "sleep", seconds: args.options.interval };
      default: {
        const exhaustive: never = evaluation;
        return exhaustive;
      }
    }
  };
  return pollUntilTerminal({
    dependencies: args.dependencies,
    options: args.options,
    stamp,
    step,
  });
}

#!/usr/bin/env python3
"""FactoryWeaver reference-only CLI: no shell, network, host write, or PR authority."""
from __future__ import annotations
import argparse
import json
import sys
from pathlib import Path
from jsonschema import Draft202012Validator, ValidationError

ROOT = Path(__file__).resolve().parents[1]
SCHEMA = ROOT / "contracts/v1/knowledge-record.schema.json"
REGISTRY = ROOT / "contracts/v1/adapter-registry.schema.json"
_REGISTRY_ABSENT = object()

class ContractError(ValueError):
    pass

def _unique_json_fields(pairs):
    fields = {}
    for key, value in pairs:
        if key in fields:
            raise ContractError("duplicate_json_key:" + key)
        fields[key] = value
    return fields

def load(path):
    return json.loads(Path(path).read_text(encoding="utf-8"),
                      object_pairs_hook=_unique_json_fields)

def _check_unique(name, items):
    if len(items) != len(set(items)):
        raise ContractError("duplicate_" + name)

def verify(record):
    Draft202012Validator(load(SCHEMA)).validate(record)
    sources = {s["source_id"]: s for s in record["sources"]}
    _check_unique("sources", [s["source_id"] for s in record["sources"]])
    _check_unique("requirements", [r["id"] for r in record["requirements"]])
    _check_unique("decisions", [d["id"] for d in record.get("decisions", [])])
    _check_unique("cards", [c["stable_id"] for c in record["cards"]])
    _check_unique("canonical_keys", [c["canonical_key"] for c in record["cards"]])
    _check_unique("action_requests", [a["request_id"] for a in record["action_requests"]])
    targets = {r["id"] for r in record["requirements"]}
    targets |= {c["stable_id"] for c in record["cards"]}
    targets |= {d["id"] for d in record.get("decisions", [])}
    for s in record["sources"]:
        pinned = s.get("integrity") == "PINNED_SHA256"
        if pinned != bool(s.get("sha256")):
            raise ContractError("invalid_source_pin:" + s["source_id"])
    def sources_exist(refs, label):
        if not set(refs).issubset(sources):
            raise ContractError("unknown_source:" + label)
    for r in record["requirements"]:
        sources_exist(r["source_ids"], r["id"])
        if not set(r.get("depends_on", [])).issubset(targets):
            raise ContractError("unknown_requirement_dependency:" + r["id"])
        if r["engineering_status"] in ("TESTED_SCOPED", "ACTIVATED"):
            raise ContractError("untrusted_test_claim:" + r["id"])
        if r["delivery_status"] == "RELEASE_CONFIRMED":
            raise ContractError("untrusted_delivery_claim:" + r["id"])
    # A typed dependency graph may be consulted by other hosts. Refuse
    # cyclic requirement prerequisites instead of projecting an apparent READY.
    requirements_by_id = {r["id"]: r for r in record["requirements"]}
    visiting, visited = set(), set()
    def visit_requirement(key):
        if key in visiting:
            raise ContractError("requirement_dependency_cycle:" + key)
        if key in visited:
            return
        visiting.add(key)
        for dep in requirements_by_id[key].get("depends_on", []):
            if dep in requirements_by_id:
                visit_requirement(dep)
        visiting.remove(key)
        visited.add(key)
    for key in requirements_by_id:
        visit_requirement(key)
    for c in record["cards"]:
        sources_exist(c["evidence_ids"], c["stable_id"])
        if any(edge["target"] not in targets for edge in c["typed_links"]):
            raise ContractError("unknown_typed_link:" + c["stable_id"])
    for d in record.get("decisions", []):
        sources_exist(d["source_ids"], d["id"])
        if d["human_confirmed"]:
            # A record-controlled SHA-256 field proves no human identity or consent.
            # This reference CLI has no independently trusted human-input owner.
            # A future host adapter must verify the raw decision outside this
            # untrusted exchange before issuing any confirmation projection.
            raise ContractError("human_confirmation_owner_required:" + d["id"])
        elif d.get("decision") is not None or d.get("confirmation_ref"):
            raise ContractError("unconfirmed_decision:" + d["id"])
    for a in record["action_requests"]:
        for field in ("kind", "requirement_id"):
            if field in a["target"] and not isinstance(a["target"][field], str):
                raise ContractError("invalid_action_target:" + a["request_id"] + ":target." + field + ":expected_string")
        if a["effect_authority"] or a["registered"] or a["status"] in ("READY", "RUNNING", "OBSERVED") or a.get("observed") is not None:
            raise ContractError("untrusted_action_claim:" + a["request_id"])
    # Progress is an untrusted author-supplied summary, not a host receipt.
    # The public reference validator must not accept completion or invented
    # states that it has no independently verified owner evidence for.
    allowed_progress_states = {
        "knowledge": {"UNKNOWN", "ANCHORED", "CONFLICTED", "SPECIFIED", "HUMAN_ANSWER_MISSING"},
        "engineering": {"NOT_STARTED", "UNASSESSED", "CODE_OBSERVED", "CONTRACT_DEFINED"},
        "delivery": {"NOT_STARTED", "BLOCKED", "OWNER_WAIT"},
    }
    for axis, allowed in allowed_progress_states.items():
        if record["progress"][axis]["state"] not in allowed:
            raise ContractError("unsupported_progress_state:" + axis)
        sources_exist(record["progress"][axis]["evidence_refs"], axis)
    return {"valid": True, "requirements": len(record["requirements"]), "cards": len(record["cards"]), "proof_ceiling": "SCHEMA_FIXTURE_ONLY", "effect_authority": False}

def project(record):
    verify(record)
    decisions = {d["id"]: d for d in record.get("decisions", [])}
    requirements_by_id = {r["id"]: r for r in record["requirements"]}
    cards_by_id = {c["stable_id"]: c for c in record["cards"]}
    sources_by_id = {source["source_id"]: source for source in record["sources"]}
    evaluated = {}

    def evaluate(req_id):
        # Verification already rejects cyclic requirement dependencies.
        if req_id in evaluated:
            return evaluated[req_id]
        req = requirements_by_id[req_id]
        dependencies = req.get("depends_on", [])
        unresolved = [ref for ref in dependencies
                      if ref in decisions and not decisions[ref]["human_confirmed"]]
        unpinned = [ref for ref in req["source_ids"]
                    if sources_by_id[ref].get("integrity") != "PINNED_SHA256"]
        # Knowledge claims do not override missing prerequisites. Walk the
        # actual dependency DAG, including decisions buried in another REQ.
        prerequisites = [ref for ref in dependencies
                         if (ref in requirements_by_id and
                             evaluate(ref)[0] not in ("READY_FOR_OWNER_REVIEW", "SPECIFICATION_ONLY")) or
                            (ref in cards_by_id and
                             cards_by_id[ref]["series"] in ("K", "X") and
                             cards_by_id[ref]["status"] == "ACTIVE")]
        if unresolved:
            status, missing = "WAIT_FOR_HUMAN", unresolved
        elif prerequisites:
            status, missing = "WAIT_FOR_PREREQUISITE", prerequisites
        elif req["knowledge_status"] == "CONFLICTED":
            status, missing = "CONTESTED", []
        elif req["knowledge_status"] == "UNKNOWN":
            status, missing = "WAIT_FOR_EVIDENCE", []
        elif unpinned:
            status, missing = "WAIT_FOR_SOURCE_PIN", unpinned
        elif req["engineering_status"] == "UNASSESSED":
            status, missing = "READY_FOR_OWNER_REVIEW", []
        else:
            status, missing = "SPECIFICATION_ONLY", []
        evaluated[req_id] = (status, missing)
        return evaluated[req_id]

    result = []
    for req in record["requirements"]:
        status, missing = evaluate(req["id"])
        result.append({"requirement": req["id"], "state": status, "missing": missing,
                       "knowledge": req["knowledge_status"],
                       "engineering": req["engineering_status"],
                       "delivery": req["delivery_status"], "authorizes_effects": False})
    return {"protocol": "factoryweaver/v1", "subject": record["subject"]["id"],
            "projection": result, "operation_scope": "READ_ONLY_NO_EXECUTION",
            "completion": "COMPILED_ONLY"}

def route(record, registry=_REGISTRY_ABSENT):
    # Bind readiness to the named requirement for validation/readback. A
    # registered-looking capability cannot bypass unresolved human decisions.
    projections = {row["requirement"]: row for row in project(record)["projection"]}
    requirements_by_id = {r["id"]: r for r in record["requirements"]}
    cards_by_id = {c["stable_id"]: c for c in record["cards"]}
    decisions_by_id = {d["id"]: d for d in record.get("decisions", [])}
    sources_by_id = {s["source_id"]: s for s in record["sources"]}
    operations = {}
    if registry is not _REGISTRY_ABSENT:
        Draft202012Validator(load(REGISTRY)).validate(registry)
        for entry in registry["operations"]:
            op = entry["operation_id"]
            if op in operations:
                raise ContractError("duplicate_registry_operation:" + op)
            operations[op] = entry
    results = []
    for a in record["action_requests"]:
        entry = operations.get(a["operation_id"])
        status = "HOST_REGISTRY_REQUIRED"
        owner = entry["owner"] if entry else None
        requirement_id = a["target"].get("requirement_id")
        requirement_state = projections.get(requirement_id, {}).get("state")
        if entry:
            if not entry["enabled"]:
                status = "CAPABILITY_DISABLED"
            elif a["mode"] not in entry["allowed_modes"] or a["target"].get("kind") not in entry["target_kinds"]:
                status = "REGISTRY_SCOPE_MISMATCH"
            elif a["intent"] != "resolve_unknown" and not requirement_id:
                status = "REQUIREMENT_BINDING_REQUIRED"
            elif requirement_id is not None and requirement_id not in projections:
                status = "UNKNOWN_REQUIREMENT"
            elif a["intent"] != "resolve_unknown" and requirement_state not in ("READY_FOR_OWNER_REVIEW", "SPECIFICATION_ONLY"):
                status = "REQUIREMENT_BLOCKED"
            else:
                status = "REGISTERED_CANDIDATE_ONLY"
                if entry.get("requires_pinned_source", False):
                    source_ids = set(sources_by_id)
                    if requirement_id is not None:
                        source_ids = set()
                        pending, seen = [requirement_id], set()
                        while pending:
                            dependency = pending.pop()
                            if dependency in seen:
                                continue
                            seen.add(dependency)
                            if dependency in requirements_by_id:
                                req = requirements_by_id[dependency]
                                source_ids.update(req["source_ids"])
                                pending.extend(req.get("depends_on", []))
                            if dependency in cards_by_id:
                                source_ids.update(cards_by_id[dependency]["evidence_ids"])
                            if dependency in decisions_by_id:
                                source_ids.update(decisions_by_id[dependency]["source_ids"])
                    if any(sources_by_id[ref].get("integrity") != "PINNED_SHA256"
                           for ref in source_ids):
                        status = "WAIT_FOR_SOURCE_PIN"
        results.append({"request_id": a["request_id"], "operation_id": a["operation_id"],
                        "route": status, "owner": owner,
                        "requirement_state": requirement_state, "can_execute": False})
    return {"requests": results, "effects": 0, "authority": "NONE"}

def cards(record):
    verify(record)
    out = ["# FactoryWeaver — Knowledge / Engineering / Delivery", "", "| REQ | Knowledge | Engineering | Delivery |", "|---|---|---|---|"]
    for r in record["requirements"]:
        out.append(f"| {r['id']} | {r['knowledge_status']} | {r['engineering_status']} | {r['delivery_status']} |")
    for c in record["cards"]:
        out.extend(["", f"## {c['stable_id']} | {c['title']}", "", c["payload"], "", "**Evidence:** " + (", ".join(c["evidence_ids"]) or "NONE"), "**Typed Links:** " + (", ".join(f"{e['relation']} → {e['target']}" for e in c["typed_links"]) or "NONE")])
    return "\n".join(out) + "\n"

def cards_json(record):
    verify(record)
    return {"cards": [{"id": c["stable_id"], "type": c["series"],
                       "title": c["title"], "body": c["payload"],
                       "source_refs": c["evidence_ids"]}
                      for c in record["cards"]], "notes": []}

def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=("validate", "project", "route", "cards", "cards-json"))
    parser.add_argument("input")
    parser.add_argument("--registry", help="Optional host capability registry for advisory routing only")
    args = parser.parse_args(argv)
    try:
        record = load(args.input)
        output = {
            "validate": lambda: verify(record),
            "project": lambda: project(record),
            "route": lambda: route(record) if args.registry is None else route(record, load(args.registry)),
            "cards": lambda: cards(record),
            "cards-json": lambda: cards_json(record),
        }[args.command]()
        print(json.dumps(output, ensure_ascii=False, sort_keys=True) if not isinstance(output, str) else output, end="\n" if not isinstance(output, str) else "")
        return 0
    except (OSError, ValueError, ValidationError, ContractError) as e:
        print(json.dumps({"valid": False, "error": str(e)}), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const scriptsDirectory = import.meta.dir;
const nodeModulesDirectory = join(scriptsDirectory, "node_modules");
const commanderPackagePath = join(
  nodeModulesDirectory,
  "commander",
  "package.json"
);
const installKeyPath = join(
  nodeModulesDirectory,
  ".poteto-mode-tools-install-key"
);

function currentInstallKey(): string {
  return createHash("sha256")
    .update(readFileSync(join(scriptsDirectory, "package.json")))
    .update("\0")
    .update(readFileSync(join(scriptsDirectory, "bun.lock")))
    .digest("hex");
}

export function ensureDependenciesInstalled(): void {
  const installKey = currentInstallKey();
  if (
    existsSync(commanderPackagePath) &&
    existsSync(installKeyPath) &&
    readFileSync(installKeyPath, "utf8").trim() === installKey
  ) {
    return;
  }

  const result = Bun.spawnSync(
    [process.execPath, "install", "--frozen-lockfile"],
    { cwd: scriptsDirectory }
  );
  if (result.exitCode !== 0) {
    process.stdout.write(result.stdout);
    process.stderr.write(result.stderr);
    throw new Error(
      `bun install --frozen-lockfile exited with status ${result.exitCode}`
    );
  }
  if (!existsSync(commanderPackagePath)) {
    throw new Error(
      "bun install --frozen-lockfile completed without installing commander"
    );
  }

  writeFileSync(installKeyPath, `${installKey}\n`);

  const restarted = Bun.spawnSync([process.execPath, ...process.argv.slice(1)], {
    cwd: process.cwd(),
    env: process.env,
    stdin: "inherit",
    stdout: "inherit",
    stderr: "inherit",
  });
  process.exit(restarted.exitCode ?? 1);
}

import { describe, expect, it } from "bun:test";
import { WatcherQueryError } from "./github.ts";
import {
  applyQueueSnapshot,
  assessGitHubMerge,
  classifyPr,
  createQueueState,
  evaluateQueue,
  planQueue,
  queryBackoffSeconds,
  readSnapshot,
  runQueued,
  selectTierMajorStackDecision,
} from "./policy.ts";
import {
  fakeReader,
  failedCheck,
  passingCheck,
  pendingCheck,
} from "./fakes.test-helper.ts";
import type {
  GitHubReader,
  NonEmpty,
  PollingOptions,
  PrContext,
  ProgressVerdict,
  PullRequestFacts,
  RollupState,
} from "./types.ts";
import { parsePrNumber } from "./types.ts";

const context = (number: number): PrContext => ({
  owner: "owner",
  repo: "repo",
  number: parsePrNumber(number),
});
const options = {
  interval: 10,
  sweepInterval: 300,
  timeout: 0,
  maxQueryErrors: 5,
  allowDraft: false,
} satisfies PollingOptions;

describe("readiness truth table", () => {
  it("covers every specified row and every UNKNOWN rollup value", () => {
    const cases: readonly [
      PullRequestFacts["mergeStateStatus"],
      RollupState,
      "allowed" | "refused",
    ][] = [
      ["BLOCKED", "FAILURE", "refused"],
      ["BLOCKED", "ERROR", "refused"],
      ["BLOCKED", "PENDING", "allowed"],
      ["UNSTABLE", "FAILURE", "allowed"],
      ["UNKNOWN", "ERROR", "allowed"],
      ["UNKNOWN", "EXPECTED", "allowed"],
      ["UNKNOWN", "FAILURE", "allowed"],
      ["UNKNOWN", "PENDING", "allowed"],
      ["UNKNOWN", "SUCCESS", "allowed"],
      ["UNKNOWN", null, "allowed"],
      ["CLEAN", "SUCCESS", "allowed"],
    ];
    for (const [mergeStateStatus, headRollupState, expected] of cases) {
      expect(
        assessGitHubMerge({ mergeStateStatus, headRollupState }).kind
      ).toBe(expected);
    }
  });

  it("turns a clean visible list plus GitHub refusal into an explicit CI blocker", async () => {
    const reader = fakeReader({
      facts: { mergeStateStatus: "BLOCKED" },
      fastPath: { kind: "checks", checks: [passingCheck()] },
      commitRollups: [{ oid: "head", state: "FAILURE" }],
    });
    const snapshot = await readSnapshot({
      reader,
      context: context(1),
      pendingHistory: "include",
      allowDraft: false,
    });
    expect(snapshot.kind).toBe("open");
    if (snapshot.kind !== "open") throw new Error("expected open snapshot");
    expect(snapshot.ci.kind).toBe("ci-github-rejected");
    expect(classifyPr(snapshot)).toMatchObject({
      kind: "blocker",
      blocker: { kind: "failing-checks" },
    });
  });
});

describe("snapshot query planning", () => {
  it("does not query commit rollups while queued checks are pending", async () => {
    const reader = fakeReader({
      fastPath: { kind: "checks", checks: [pendingCheck()] },
    });
    const snapshot = await readSnapshot({
      reader,
      context: context(2),
      pendingHistory: "omit",
      allowDraft: false,
    });
    expect(snapshot.kind).toBe("open");
    if (snapshot.kind !== "open") throw new Error("expected open snapshot");
    expect(snapshot.ci.kind).toBe("ci-pending");
    expect(reader.calls).toEqual([
      "pullRequest",
      "reviewThreads",
      "checksFastPath",
    ]);
  });

  it("queries rollups for settled and failed lists", async () => {
    const settled = fakeReader();
    await readSnapshot({
      reader: settled,
      context: context(3),
      pendingHistory: "omit",
      allowDraft: false,
    });
    expect(settled.calls).toContain("commitRollups");

    const failed = fakeReader({
      fastPath: { kind: "checks", checks: [failedCheck()] },
    });
    await readSnapshot({
      reader: failed,
      context: context(4),
      pendingHistory: "omit",
      allowDraft: false,
    });
    expect(failed.calls).toContain("commitRollups");
  });

  it("short-circuits merged rows before threads and checks", async () => {
    const reader = fakeReader({
      facts: { state: "MERGED", mergedAt: "2026-07-26T00:00:00Z" },
    });
    expect(
      (
        await readSnapshot({
          reader,
          context: context(5),
          pendingHistory: "include",
          allowDraft: false,
        })
      ).kind
    ).toBe("merged");
    expect(reader.calls).toEqual(["pullRequest"]);
  });
});

it("scans stacks tier-major so an upstack conflict outranks frontier CI", async () => {
  const frontier = await readSnapshot({
    reader: fakeReader({
      fastPath: { kind: "checks", checks: [failedCheck()] },
      commitRollups: [{ oid: "head", state: "FAILURE" }],
    }),
    context: context(10),
    pendingHistory: "omit",
    allowDraft: false,
  });
  const upstack = await readSnapshot({
    reader: fakeReader({ facts: { mergeable: "CONFLICTING" } }),
    context: context(11),
    pendingHistory: "omit",
    allowDraft: false,
  });
  const decision = selectTierMajorStackDecision([frontier, upstack]);
  expect(decision).toMatchObject({
    kind: "blocker",
    blocker: { kind: "merge-conflicts", pr: { number: 11 } },
  });
});

it("attributes a stack wait to the PR whose checks are pending, not the bottom", async () => {
  const readyBottom = await readSnapshot({
    reader: fakeReader(),
    context: context(20),
    pendingHistory: "omit",
    allowDraft: false,
  });
  const pendingUpstack = await readSnapshot({
    reader: fakeReader({
      fastPath: { kind: "checks", checks: [pendingCheck("upstack-build")] },
    }),
    context: context(21),
    pendingHistory: "omit",
    allowDraft: false,
  });
  const decision = selectTierMajorStackDecision([readyBottom, pendingUpstack]);
  expect(decision).toMatchObject({
    kind: "waiting",
    frontier: { number: 21 },
    pending: [{ name: "upstack-build" }],
  });
});

it("waits on a draft while checks are pending, then reports the draft gate", async () => {
